    borderWidth: 1,
    padding: 22,
    alignItems: 'center',
    shadowColor: '#000',
    shadowOpacity: 0.3,
    shadowRadius: 24,
    shadowOffset: { width: 0, height: 10 },
    elevation: 12,
  },
  welcomeIcon: {
    width: 54,
    height: 54,
    borderRadius: 27,
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: 14,
  },
  welcomeTitle: {
    fontSize: 20,
    fontFamily: 'Poppins-700Bold',
    textAlign: 'center',
  },
  welcomeBody: {
    fontSize: 14,
    lineHeight: 20,
    textAlign: 'center',
    marginTop: 8,
  },
  welcomeCta: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
    backgroundColor: ORANGE,
    borderRadius: 999,
    paddingVertical: 13,
    paddingHorizontal: 22,
    marginTop: 20,
    alignSelf: 'stretch',
    justifyContent: 'center',
  },
  welcomeCtaText: {
    color: '#FFFFFF',
    fontSize: 15,
    fontFamily: 'Poppins-600SemiBold',
  },
  welcomeSkip: {
    marginTop: 14,
    paddingVertical: 6,
    paddingHorizontal: 12,
  },
  welcomeSkipText: {
    fontSize: 13,
    fontFamily: 'Poppins-500Medium',
  },
  ring: {
    position: 'absolute',
    borderWidth: 2,
  },
  tooltip: {
    position: 'absolute',
  },
  tooltipCard: {
    borderRadius: 18,
    borderWidth: 1,
    padding: 16,
    shadowColor: '#000',
    shadowOpacity: 0.28,
