  },
  closeBtn: {
    position: 'absolute',
    top: scale(12),
    right: scale(12),
    width: scale(30),
    height: scale(30),
    borderRadius: 99,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'rgba(255,255,255,0.12)',
    borderWidth: 1,
    borderColor: 'rgba(255,255,255,0.18)',
  },
  heroRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: scale(12),
    marginTop: scale(18),
  },
  avatar: {
    width: scale(52),
    height: scale(52),
    borderRadius: scale(26),
    borderWidth: 2,
  },
  avatarFallback: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarText: {
    fontSize: scale(19),
    fontFamily: fonts.extrabold,
  },
  heroText: {
    flex: 1,
    paddingRight: scale(28),
  },
  heroBrand: {
    fontSize: scale(8.5),
    letterSpacing: 2,
    fontFamily: fonts.extrabold,
  },
  heroName: {
    color: '#FFFFFF',
    fontSize: scale(16),
    fontFamily: fonts.extrabold,
    marginTop: 1,
  },
  livePill: {
    alignSelf: 'flex-start',
    flexDirection: 'row',
    alignItems: 'center',
    gap: scale(5),
    marginTop: scale(7),
    backgroundColor: 'rgba(255,255,255,0.10)',
    borderWidth: 1,
    borderRadius: 999,
    paddingHorizontal: scale(9),
    paddingVertical: scale(4),
    maxWidth: '100%',
  },
  liveDot: {
    width: scale(6),
    height: scale(6),
    borderRadius: 99,
  },
  liveText: {
    color: '#FFFFFF',
    fontSize: scale(8),
