  segmentText: {
    fontSize: scale(11),
  },
  signOut: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: scale(7),
    borderRadius: scale(13),
    borderWidth: 1,
    paddingVertical: scale(11),
  },
  signOutText: {
    fontSize: scale(12),
    fontFamily: fonts.bold,
  },
});

